const Module = require('module');
const originalLoad = Module._load;
const refs = [];
let cursor = 0;
let cleanup;
const fakeReact = {
  useRef(value) {
    const index = cursor++;
    if (!refs[index]) refs[index] = { current: value };
    return refs[index];
  },
  useReducer(reducer, value) {
    const index = cursor++;
    if (!refs[index]) refs[index] = { current: value };
    return [refs[index].current, () => { refs[index].current = reducer(refs[index].current); }];
  },
  useEffect(effect) { cleanup = effect(); },
};
Module._load = function(request, parent, isMain) {
  return request === 'react' ? fakeReact : originalLoad.call(this, request, parent, isMain);
};
const pending = [];
const retries = [];
globalThis.__preparationTransport = (token) => new Promise((resolve) => pending.push({ token, resolve }));
globalThis.__schedulePreparationRetry = (callback) => { const handle = { callback, cancelled: false }; retries.push(handle); return handle; };
globalThis.__cancelPreparationRetry = (handle) => { handle.cancelled = true; };
const { usePreparation } = require('./src/usePreparation.js');
cursor = 0;
const preparation = usePreparation('a', { invalidateOnClose: true });
const flush = () => new Promise((resolve) => setImmediate(resolve));
(async () => {
  preparation.start();
  pending.shift().resolve(false);
  await flush();
  if (!preparation.snapshot().retryScheduled || preparation.snapshot().checkCount !== 1) throw new Error('pending did not schedule a retry');
  retries.shift().callback();
  pending.shift().resolve(true);
  await flush();
  let snapshot = preparation.snapshot();
  if (snapshot.loading || snapshot.retryScheduled || snapshot.completed.join() !== 'a') throw new Error('ready did not complete the active file');

  preparation.reopen('b');
  const oldRequest = pending.shift();
  preparation.close();
  oldRequest.resolve(true);
  await flush();
  if (preparation.snapshot().completed.includes('b')) throw new Error('closed activity accepted an old callback');

  preparation.reopen('c');
  const cRequest = pending.shift();
  preparation.reopen('d');
  const dRequest = pending.shift();
  cRequest.resolve(true);
  dRequest.resolve(true);
  await flush();
  snapshot = preparation.snapshot();
  if (snapshot.completed.includes('c') || !snapshot.completed.includes('d')) throw new Error('token change did not isolate callbacks');

  preparation.reopen('e');
  const eRequest = pending.shift();
  cleanup();
  eRequest.resolve(true);
  await flush();
  if (preparation.snapshot().completed.includes('e')) throw new Error('unmount accepted an old callback');
  console.log('lifecycle polling checks passed');
})().catch((error) => { console.error(error); process.exitCode = 1; });
